(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100+Math.cos(t*0.3)*30, 80+Math.cos(t*0.4)*50+Math.sin(t*0.2)*20, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100+Math.sin(t*0.25)*40, 160+Math.sin(t*0.7)*50+Math.cos(t*0.35)*25, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140+Math.cos(t*0.15)*50, 120+Math.cos(t*0.5+1)*90+Math.sin(t*0.1)*30, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80+Math.sin(t*0.4+2)*20, 180+Math.sin(t*0.6+3)*60+Math.cos(t*0.3+1)*15, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90+Math.cos(t*0.2+3)*25, 60+Math.cos(t*0.9+2)*70+Math.sin(t*0.45+1)*20, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120+Math.sin(t*0.18+4)*35, 200+Math.sin(t*0.55)*80+Math.cos(t*0.28+2)*20, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*40, 0.14, 2.1],
    [400+Math.cos(t*0.38+2)*60, 220+Math.sin(t*0.52+4)*50, 0.11, 1.8]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.065+t*1.8)*Math.cos(sy*0.05-t*1.3)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4 + Math.sin(dist*0.08-ang*6+t*0.8)*0.15 + Math.cos(dist*0.03+ang*2-t*0.6)*0.1;
  const fineAct = Math.sin(sx*0.2+Math.sin(sy*0.15+t*0.5)*2)*Math.cos(sy*0.18-t*0.3);
  const fineInh = Math.sin((sx+sy)*0.12+t*0.7)*Math.cos((sx-sy)*0.1-t*0.5);
  const fine = Math.tanh((fineAct - fineInh*0.6)*1.2)*0.2;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const cellPhase = sx*0.15+sy*0.15+Math.sin(sx*0.08-sy*0.06+t)*3;
  const cell = Math.tanh((Math.sin(cellPhase) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const harm2 = Math.sin(dist*0.07+ang*5-t*2.0)*Math.cos(dist*0.04-ang*3+t*1.5)*0.15;
  const blend = reaction*0.55 + cell*0.2 + fine*0.15 + harm2*0.1, v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,45,95],[18,95,125],[30,150,135],[160,190,80],[220,170,50],[210,100,55],[165,45,70],[90,18,60],[40,12,50],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i, sf = f*f*(3-2*f);
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25, edge = 1.0+Math.pow(Math.abs(reaction),2.5)*0.2, glow = Math.max(0,Math.abs(reaction)-0.6)*0.5;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge + glow*80)|0)
  ];
}
